def embed(texts, input_type="search_query"):
    return client.embed(texts=texts, model=MODEL, input_type=input_type)

def index_chunks(ids, chunks):
    store.upsert(zip(ids, embed(chunks)))

def search(question, k=10):
    return store.query(embed([question])[0], k=k)

DOCS = ["D1", "D2", "D3", "D4"]
GOLD = {"Q1": "D2", "Q2": "D4"}

def recall_at_1(q_type, d_type):
    hits = 0
    for q, gold in GOLD.items():
        qv = embed(q, q_type)
        scores = {d: cos(qv, embed(d, d_type)) for d in DOCS}
        top = max(scores, key=scores.get)
        hits += (top == gold)
    return hits / len(GOLD)

# sanity check: is the role actually applied?
s = cos(embed("Q1", "query"), embed("Q1", "document"))
assert s < 0.999, "input type ignored"

for cfg in [("query", "document"), ("document", "document"), ("query", "query")]:
    print(cfg, recall_at_1(*cfg))
